import { MakeLogicType, afterMount, connect, kea, listeners, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { organizationLogic } from 'scenes/organizationLogic'

import type { OrganizationType } from '~/types'

import { departedList } from 'products/platform_features/frontend/generated/api'
import type { DepartedProjectApi } from 'products/platform_features/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface departedProjectsLogicValues {
    currentOrganization: OrganizationType | null // organizationLogic
    departedProjects: DepartedProjectApi[] | null
    departedProjectsLoading: boolean
    mostRecentDeparture: DepartedProjectApi | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface departedProjectsLogicActions {
    loadDepartedProjects: () => any
    loadDepartedProjectsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDepartedProjectsSuccess: (
        departedProjects: DepartedProjectApi[],
        payload?: any
    ) => {
        departedProjects: DepartedProjectApi[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface departedProjectsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        mostRecentDeparture: (departedProjects: DepartedProjectApi[] | null) => DepartedProjectApi | null
    }
}

export type departedProjectsLogicType = MakeLogicType<
    departedProjectsLogicValues,
    departedProjectsLogicActions,
    Record<string, any>,
    departedProjectsLogicMeta
>

export const departedProjectsLogic = kea<departedProjectsLogicType>([
    path(['scenes', 'project', 'departedProjectsLogic']),
    connect(() => ({
        values: [organizationLogic, ['currentOrganization']],
    })),
    loaders(({ values }) => ({
        departedProjects: [
            // `null` is "not asked yet", so a screen can tell an empty answer from a pending one
            null as DepartedProjectApi[] | null,
            {
                loadDepartedProjects: async (): Promise<DepartedProjectApi[]> =>
                    await departedList(values.currentOrganization!.id),
            },
        ],
    })),
    selectors({
        mostRecentDeparture: [
            (s) => [s.departedProjects],
            (departedProjects: DepartedProjectApi[] | null): DepartedProjectApi | null => departedProjects?.[0] ?? null,
        ],
    }),
    listeners(({ actions }) => ({
        // The screens that show a departure can mount before the organization has loaded, and the
        // endpoint is organization-scoped, so the load is gated on whichever of the two lands last.
        [organizationLogic.actionTypes.loadCurrentOrganizationSuccess]: () => {
            actions.loadDepartedProjects()
        },
    })),
    afterMount(({ actions, values }) => {
        if (values.currentOrganization) {
            actions.loadDepartedProjects()
        }
    }),
])
